import logging
import socket
import pprint
from typing import Union, Optional
from taf.sbts.oam.coam.admin import admin, AdminConnection
from taf.rfrl.utilities.cloud_manager import is_cm_execution
from taf.rfrl.utilities.messenger import send_email_with_default_template, EmailBuilder
from taf.rfrl.utilities.scout_interface import GenericScout
from taf.rfrl.utilities.robot.general import import_library_to_robot_framework_namespace, run_robot_keyword
from taf.rfrl.common_resources.reporting_portal.exceptions import BtsMetadataReportingError


class bts_metadata:
    LIB_PATH = 'taf.rfrl.common_resources.reporting_portal.bts_metadata'

    def __init__(self):
        self.all_scf_ids = {}
        self._scout = GenericScout()
        self._admin = admin()

    def add_bts_metadata_to_report(self, bts_params: Union[list, dict]) -> None:
        """
        Add BTS metadata to the report:
            mrbts_id, build, role(SA/NSA) and scout_scf_id(used to calculating configuration ID).
            Data will be visible under the 'system_under_test' key in the ReP JSON report.
        :param bts_params: List of dictionaries with BTS parameters or single dictionary with BTS parameters.
        eg  [{'admin_connection': 'BTS0_ADMIN', 'scout_bts_name': 'BTS0_NAME'}, ...]
        or just
            {'admin_connection': 'BTS0_ADMIN', 'scout_bts_name': 'BTS0_NAME'}
        """

        self.all_scf_ids = {}
        exceptions = {}
        if isinstance(bts_params, dict):
            bts_params = [bts_params]

        try:
            # Current solution for reporting configuration ID
            run_robot_keyword(f'{bts_metadata.LIB_PATH}.add_scout_scf_id_to_test_data',
                              bts_params[0]['scout_bts_name'])
        except Exception as e:
            exceptions['Current_solution'] = e
            logging.debug(f"Failed to add SCF ID to test data: {e}")

        # New way of reporting configuration ID - so far not implemented in ReP
        for single_bts_params in bts_params:
            try:
                run_robot_keyword(f'{bts_metadata.LIB_PATH}.add_bts_environment_info_to_report',
                                  single_bts_params['admin_connection'], single_bts_params['scout_bts_name'])
            except Exception as e:
                exceptions[single_bts_params['scout_bts_name']] = e
                logging.debug(f"Failed to add BTS metadata for {single_bts_params['scout_bts_name']}: {e}")

        if exceptions:
            raise BtsMetadataReportingError(f"Failed to add BTS metadata for the following BTSs: {exceptions}")

    def add_scout_scf_id_to_test_data(self, scout_bts_name: Optional[str] = None,
                                      force: Optional[bool] = True) -> None:
        """
        .. note::
            Current solution reporting configuration ID - will be deleted in future

        Add SCF ID to test data.
        :param scout_bts_name: Name of the scout BTS. If not provided, it will be taken automatically based on
                               TesPC VM hostname
        :param force: Force fetching SCF ID from Scout even if it was already fetched before.
        """
        import_library_to_robot_framework_namespace(name='taf.sw.reporting_portal')
        scout_bts_name = scout_bts_name or self._get_main_bts_name()
        logging.info(f"SCOUT_BTS_NAME: {scout_bts_name}")

        use_scout_internal_id = not is_cm_execution()
        logging.info(f"USE_SCOUT_INTERNAL_ID: {use_scout_internal_id}")

        scout_scf_id = self.all_scf_ids.get(scout_bts_name)
        if scout_scf_id is None or force:
            scout_scf_id = self.get_scout_scf_id(scout_bts_name, use_scout_internal_id)
        logging.info(f"SCOUT_SCF_ID: {scout_scf_id}")

        if use_scout_internal_id:
            run_robot_keyword("taf.sw.reporting_portal.add_to_test_data", {"tc_execution_id": scout_scf_id})

    def add_bts_environment_info_to_report(self, admin_connection: Union[str, AdminConnection],
                                           scout_bts_name: Optional[str] = None,
                                           force: Optional[bool] = False) -> None:
        """
        Add BTS information to the report:  mrbts_id, build, role(SA/NSA) and
                                            scout_scf_id(used to calculating configuration ID).
                                            Data will be visible under the 'system_under_test' key in the ReP JSON report.
        :param admin_connection:    admin connection or alias
        :param scout_bts_name:      scout BTS name - is used only when scout_scf_id is not provided.
                                                     if scout_bts_name not provided, it will be taken
                                                     automatically based on VM name or CONFIGURATION param
        :param force:               Force fetching SCF ID from Scout even if it was already fetched before.
        """
        bts_info = self._get_bts_environment_info(admin_connection, scout_bts_name=scout_bts_name, force=force)
        robot_args = [
            f"mrbts_id={bts_info['id']}",
            f"build={bts_info['build']}",
            f"scout_scf_id={bts_info['scout_scf_id']}"
        ]
        if bts_info['role'] in ['SA', 'NSA']:
            robot_args.append(f"role={bts_info['role']}")
        else:
            logging.debug(f"At this moment ROLE={bts_info['role']} can not be reported")
        import_library_to_robot_framework_namespace(name='taf.sw.reporting_portal')
        run_robot_keyword('taf.sw.reporting_portal.add_bts_to_report', *robot_args)
        if bts_info['raised_exception']:
            additional_info = self._generate_additional_info(bts_info)
            logging.info("Sending email ...")
            logging.debug(f"Additional info:\n{additional_info}")
            send_email_with_default_template(
                subject=f"Fetching SCF ID from Scout failed for {bts_info['scout_bts_name']}",
                sender='vrf.tag@nokia.com',
                additional_info=additional_info,
                add_team_email=False,
                regards='VRF TAG Team',
                email_builder=EmailBuilder(scout_bts_name=bts_info['scout_bts_name'])
            )
            raise bts_info['raised_exception']

    def get_scout_scf_id(self, scout_bts_name: str, use_scout_internal_id: bool = True, max_attempts: int = 10,
                         interval_between_attempts: int = 5, request_scf_timeout: int = 120) -> str:
        """
        Get the SCF ID for a given scout BTS name.

        :param scout_bts_name: Name of the scout BTS.
        :param use_scout_internal_id: Whether to use the scout internal ID, defaults to True.
        :param max_attempts: Maximum number of attempts to get the SCF ID, defaults to 10.
        :param interval_between_attempts: Interval between attempts in seconds, defaults to 5.
        :param request_scf_timeout: Timeout for the SCF request in seconds, defaults to 120.
        :return: The SCF ID.
        """
        scf_id = self._scout.get_scf_id(scout_bts_name, use_scout_internal_id, max_attempts,
                                        interval_between_attempts, request_scf_timeout)
        if scf_id:
            self.all_scf_ids[scout_bts_name] = scf_id
        return scf_id

    def _get_bts_environment_info(self, admin_connection: Union[str, AdminConnection],
                                  scout_bts_name: Optional[str] = None, scout_scf_id: Optional[str] = None,
                                  force: Optional[bool] = False) -> dict:
        """
        Get BTS information which could be used under 'system_under_test' key in the ReP JSON report.

        :param admin_connection:    admin connection or alias
        :param scout_bts_name:      scout BTS name - is used only when scout_scf_id is not provided.
                                                     if scout_bts_name not provided, it will be taken
                                                     automatically based on VM name or CONFIGURATION param
        :param scout_scf_id:        scout SCF ID - if not provided, it will be taken automatically
                                    it could be also provided as dictionary with MRBTS-<ID> as key and SCF ID as value
                                    eg. {'MRBTS-77016': 76765408}
        :param force:               Force fetching SCF ID from Scout even if it was already fetched before.
        :return: dict eg:
            {
                'id': 'MRBTS-77016',
                'type': 'bts',
                'build': 'SBTS24R2_ENB_9999_240301_000018',
                'role': 'SA',
                'scout_scf_id': 76765408,
                'scout_bts_name': 'BTS0_NAME',
            }

        """
        bts_details = {}
        raised_exception = None
        bts_info = self._admin.get_bts_info(connection=admin_connection, timeout=30)
        scout_scf_id = scout_scf_id or self.all_scf_ids.get(scout_bts_name)
        if scout_scf_id is None or force:
            try:
                scout_bts_name = scout_bts_name or self._get_main_bts_name()
                bts_details = self._scout.get_bts_details(scout_bts_name, include_monitor=True)
                logging.debug(f"Scout BTS details: {bts_details}")
                logging.info(f"Get scout SCF ID for: {scout_bts_name}")
                scout_scf_id = self.get_scout_scf_id(scout_bts_name)
                logging.info(f"SCF ID: {scout_scf_id}")
            except Exception as e:
                raised_exception = e

        return {
            'id': self._get_mrbts_id(bts_info),
            'type': 'bts',
            'build': self._get_bts_build(bts_info),
            'role': self._get_bts_role(bts_info),
            'scout_scf_id': scout_scf_id,
            'scout_bts_name': scout_bts_name,
            'bts_details': bts_details,
            'raised_exception': raised_exception
        }

    @staticmethod
    def _get_mrbts_id(bts_info: dict) -> str:
        """
        Get MRBTS ID from BTS info.
        :param bts_info: BTS info.
        :return: MRBTS ID eg MRBTS-77016
        """
        return bts_info['id']['configuration']

    @staticmethod
    def _get_bts_build(bts_info: dict) -> str:
        """
        Get BTS build from BTS info.
        :param bts_info: BTS info.
        :return: BTS build, eg SBTS24R2_ENB_9999_240301_000018
        """
        return bts_info['swInfo'].get('swVersion')

    @staticmethod
    def _get_bts_role(bts_info: dict) -> str:
        """
        Get BTS role from BTS info.
        :param bts_info: BTS info.
        :return: BTS role, eg SA or NSA
        """
        return bts_info.get('gNbCuType')

    @staticmethod
    def _get_main_bts_name() -> str:
        """
        Get main BTS name based on VM hostname.
        :return: Main BTS name.
        """
        return socket.gethostname().replace('-', '_').rstrip('_integration').upper()

    def _generate_additional_info(self, bts_info: dict) -> str:
        """
        Generate additional information for the email when fetching SCF ID fails.
        :param bts_info: BTS information dictionary.
        :return: Additional information as a HTML formatted string.
        """
        bts_connectivity_docs_link = 'https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1613285334'
        scf_analysis_investigation = 'https://confluence.ext.net.nokia.com/display/LRP/SCF+Analysis'
        scout_analysis_link = self._scout.get_url_link_for_scf_analysis(bts_info['scout_bts_name'],
                                                                        bts_info['scout_scf_id'])
        rep_analysis_link = self._get_rep_analysis_link(bts_info['scout_bts_name'], bts_info['scout_scf_id'])
        tl_url = self._scout.get_url_link_for_testline(bts_info['scout_bts_name'])
        bts_data = bts_info['bts_details'].get('data')
        bts_monitor_status = self._get_monitor_status_from_bts_details(bts_info['bts_details'])
        info = {
            'scout_bts_name': f"<a href='{tl_url}'>{bts_info['scout_bts_name']}</a>",
            'bts_mplane_ip': bts_data['attributes']['mplane'] if bts_data else '',
            'scout_testline_status': bts_data['attributes']['infomodel']['status'] if bts_data else '',
            # 'monitor_type': 'TBD',
            'scf_analysis_scout_view': f"<a href='{scout_analysis_link}'>LINK</a>",
            'scf_analysis_rep_view': f"<a href='{rep_analysis_link}'>LINK</a>",
            'scout_monitor_status': f"<br>{pprint.pformat(bts_monitor_status, indent=4)}",
        }
        docs_info = f"""
        Documentation:
        <ul>
            <li><a href='{bts_connectivity_docs_link}'>BTS connectivity investigation</a></li>
            <li><a href='{scf_analysis_investigation}'>SCF Analysis investigation</a></li>
        </ul>
        """
        info_html = ""
        for name, value in info.items():
            info_html = info_html + "{:<32}{}\n".format(name.upper(), value)
        info_html = "<pre>{}</pre>".format(info_html)

        additional_info = rf"""
        Fetch SCF ID failed due to {bts_info['raised_exception']}.<br>
        Below are useful pieces of information that may assist during debugging.<br><br>
        {info_html}
        <br>
        {docs_info}
        """
        return additional_info

    @staticmethod
    def _get_monitor_status_from_bts_details(bts_details):
        if bts_details.get('included'):
            for attribute in bts_details.get('included'):
                if attribute['type'] == 'testline_monitor':
                    return attribute['meta']

    @staticmethod
    def _get_rep_analysis_link(scout_bts_name: str, scout_scf_id: str = None) -> str:
        """
        Get the ReP analysis link for a given scout BTS name.
        :param scout_bts_name: Name of the scout BTS.
        :param scout_scf_id: SCF ID of the scout BTS.
        :return: ReP analysis link.
        """
        link = fr"https://rep-portal.ext.net.nokia.com/reports/scf-analysis/?scout_testline_name={scout_bts_name}"
        if scout_scf_id:
            link = link + fr"&external_execution_id={scout_scf_id}"
        return link
